function ActivityBossChallengeDifficultyDialog:InitHandler()
    SetButtonAction(self.controller, Bind(self, self.BtnCloseOnClickHandler))

    for i = 1, 3 do
        local node = self.List:Find('LevelNode' .. i)
        if not isNull(node) then
            local btn = node:Find('Btn')
            SetButtonAction(btn, function()  
                self:CellOnClickHandler(i)
            end)
            local battleBtn = node:Find('FontStyleButton')
            SetButtonAction(battleBtn, function()
                self:BattleBtnOnClickHandler(i)
            end)
        end
    end
end

