---刷新难度node
function ActivityBossChallengeDifficultyDialog:RefreshDifficultyNode()
    local activityVo = CfUtils.GetCfVo(AutoIds.IdSetting2752, "BossChallengeActivityVo", self._activityScheduleId)
    for i, v in ipairs(self._questData) do
        local node = self.List:Find('LevelNode' .. i)
        if not isNull(node) then
            local title = node:Find("Btn/ContentGroup/TextTitle")
            CfUtils.FillText(title, v.label)
            
            local quality = node:Find("Btn/ContentGroup/ImgQuality")
            CfUtils.SetUISwitchImage(quality, v.regionLevel)
            
            local desc = node:Find('Btn/ContentGroup/IntroductionGroup/TxtContent')
            CfUtils.FillText(desc, v.desc)
            
            local goodsNode = node:Find("Btn/ContentGroup/IntroductionGroup/GoodNode")
            local env = CfUtils.GetLuaScr(goodsNode, GoodsNodePath)
            env:Reload(
                    {
                        goodsId = activityVo.ptItem,
                        text = "x" .. v.score,
                        isShowNo = true
                    }
            )
            env:SetClickButtonAction(function(goodsId)
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(goodsVo) then
                    GameUtils.ShowCommonTipsBoard(goodsNode.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
                end
            end)
        end
    end
end

---刷新node状态
function ActivityBossChallengeDifficultyDialog:RefreshNodeState()
    for i = 1, 3 do
        local node = self.List:Find('LevelNode' .. i)
        if not isNull(node) then
            local imageSelect = node:Find("Btn/ImageSelect")
            KTool.SetActive(imageSelect, i == self._selectedNode)
            local btn = node:Find("FontStyleButton")
            KTool.SetActive(btn, i == self._selectedNode)
        end
    end
end

---播放进入动画
function ActivityBossChallengeDifficultyDialog:PlayEnterAnimation()
    if self._enterAnimation then
        self.Root:Play(self._enterAnimation)
    end
end
